#include <bits/stdc++.h>
using namespace std;

int main() {
	string s, t;
	int c[500010], d[500010];
	int l, r;

	cin >> s;
	cin >> t;
	int n = s.size();
	int m = t.size();

	r = 1;
	c[0] = n;
	for (int i = 1; i < n; i++) {
		if (r == n)c[i] = n - i;
		if (i == 1) {
			while (r < n) {
				if (s[r] == s[r - i])r++;
				else break;
			}
			c[i] = r - i;
			l = i;
		}
		else if (c[i - l] < (r - i)) {
			c[i] = c[i - l];
		}
		else {
			r = max(i, r);
			while (r < n) {
				if (s[r] == s[r - i])r++;
				else break;
			}
			c[i] = r - i;
			l = i;
		}
	}

	for (int i = 0; i < m; i++)d[i] = -1;
	r = 0;
	for (int i = 0; i < m; i++) {
		if (r == m)break;
		if (i == 0) {
			while ((r < m) && (r < n)) {
				if (t[r] == s[r]) {
					d[r] = 1;
					r++;
				}
				else break;
			}
			l = 0;
		}
		else if (d[i - 1] == -1)break;
		else if (c[i - l] >= r - i) {
			while ((r < m) && ((r - i) < n)) {
				if (t[r] == s[r - i]) {
					d[r] = d[i - 1] + 1;
					r++;
				}
				else break;
			}
			l = i;
		}
	}
	cout << d[m - 1] << endl;

	return 0;
}
